hero_en='''<div class="hero"><p class="eyebrow">F# concurrency · reference &amp; field guide</p><h1>Give your state<br><span>one owner.</span></h1><p class="lead">Three small agent models for sequential work, immutable domain state and mutable registries. Learn the contracts before building your server around them.</p><div class="badges"><span>.NET 10+</span><span>Task + Channels</span><span>F# + .NET only</span><span>Works offline</span></div></div>'''
hero_ru='''<div class="hero"><p class="eyebrow">Конкурентность в F# · практическое руководство</p><h1>У каждого состояния —<br><span>один владелец.</span></h1><p class="lead">Три небольшие модели агентов для последовательной работы, неизменяемого доменного состояния и изменяемых реестров. Контракты и примеры для твоего сервера.</p><div class="badges"><span>.NET 10+</span><span>Task + Channels</span><span>Только F# + .NET</span><span>Работает офлайн</span></div></div>'''

js=r'''
(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const read=k=>{try{return localStorage.getItem(k)}catch{return null}}, save=(k,v)=>{try{localStorage.setItem(k,v)}catch{}};
const text={en:{search:'Find a section',placeholder:'Timeout, state, shutdown…',toc:'In this guide',source:'Source & quick start',copy:'Copy',copied:'Copied',copyFailed:'Select code to copy',themeDark:'Dark',themeLight:'Light',themeLabel:'Toggle color theme',all:'13 sections · press / to search',matches:n=>`${n} matching section${n===1?'':'s'}`,none:'No matching sections. Try another term or clear the search.',offline:'One file. No build. No network.',top:'Back to top ↑',nav:'Documentation sections',searchAria:'Search documentation sections'},ru:{search:'Найти раздел',placeholder:'Таймаут, состояние, shutdown…',toc:'В руководстве',source:'Исходник и краткое начало',copy:'Копировать',copied:'Скопировано',copyFailed:'Выдели код для копирования',themeDark:'Тёмная',themeLight:'Светлая',themeLabel:'Переключить цветовую тему',all:'13 разделов · / для поиска',matches:n=>`Найдено разделов: ${n}`,none:'Подходящих разделов нет. Измени запрос или очисти поиск.',offline:'Один файл. Без сборки и сети.',top:'В начало ↑',nav:'Разделы документации',searchAria:'Поиск разделов документации'}};
let lang='en', observer;
const getSections=()=>$$(`article[data-lang="${lang}"] .doc-section`);
function updateTheme(){const dark=document.documentElement.dataset.theme==='dark';$('.theme').textContent=dark?text[lang].themeLight:text[lang].themeDark;$('.theme').setAttribute('aria-label',text[lang].themeLabel);$('.theme').setAttribute('aria-pressed',String(dark));}
function filter(){const query=$('#search').value.trim().toLocaleLowerCase(lang);let count=0;for(const section of getSections()){const match=!query||section.textContent.toLocaleLowerCase(lang).includes(query);section.hidden=!match;const link=$(`.nav a[data-target="${section.dataset.section}"]`);if(link)link.hidden=!match;if(match)count++;}$('#search-status').textContent=query?text[lang].matches(count):text[lang].all;$('#no-results').hidden=count!==0;}
function buildNav(){const nav=$('.nav');nav.replaceChildren();for(const s of getSections()){const a=document.createElement('a');a.href='#'+s.id;a.dataset.target=s.dataset.section;a.textContent=s.querySelector('h2').textContent;nav.append(a);}if(observer)observer.disconnect();if('IntersectionObserver'in window){observer=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting){$$('.nav a').forEach(a=>a.removeAttribute('aria-current'));const a=$(`.nav a[data-target="${e.target.dataset.section}"]`);if(a)a.setAttribute('aria-current','location');}}},{rootMargin:'-100px 0px -65% 0px',threshold:0});getSections().forEach(s=>observer.observe(s));}}
function setLang(next,{keepSection=false}={}){if(!text[next])return;const hash=location.hash.slice(1);const slug=/^(en|ru)-/.test(hash)?hash.slice(3):'';lang=next;document.documentElement.lang=lang;save('dreamsleeve-agent-lang',lang);$$('article[data-lang]').forEach(a=>a.hidden=a.dataset.lang!==lang);$$('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===lang)));$('#search-label').textContent=text[lang].search;$('#search').placeholder=text[lang].placeholder;$('#search').setAttribute('aria-label',text[lang].searchAria);$('.nav-title').textContent=text[lang].toc;$('.nav').setAttribute('aria-label',text[lang].nav);$('#sidebar-title').textContent=text[lang].source;$('#readme-link').href=lang==='ru'?'../README.ru.md':'../README.md';$('#readme-link').textContent=lang==='ru'?'Краткое начало →':'Quick start →';$('#no-results').textContent=text[lang].none;$('#footer-note').textContent=text[lang].offline;$('#top-link').textContent=text[lang].top;$('#skip').textContent=lang==='ru'?'К содержимому':'Skip to content';$$('[data-copy]').forEach(b=>b.textContent=text[lang].copy);updateTheme();buildNav();filter();if(keepSection){const nextHash=slug?`${lang}-${slug}`:lang;try{history.replaceState(null,'','#'+nextHash)}catch{}if(slug)document.getElementById(`${lang}-${slug}`)?.scrollIntoView();}}
$('.theme').addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;save('dreamsleeve-agent-theme',theme);updateTheme();});$$('[data-language]').forEach(b=>b.addEventListener('click',()=>setLang(b.dataset.language,{keepSection:true})));
$('#search').addEventListener('input',filter);document.addEventListener('keydown',e=>{const tag=document.activeElement?.tagName;if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(tag)&&!document.activeElement?.isContentEditable){e.preventDefault();$('#search').focus();}if(e.key==='Escape'&&document.activeElement===$('#search')){$('#search').value='';filter();$('#search').blur();}});
$$('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const value=button.closest('.codeblock').querySelector('code').textContent;let ok=false;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(value);ok=true;}}catch{}if(!ok){const area=document.createElement('textarea');area.value=value;area.style.position='fixed';area.style.left='-9999px';document.body.append(area);area.select();try{ok=document.execCommand('copy')}catch{}area.remove();button.focus();}button.textContent=ok?text[lang].copied:text[lang].copyFailed;$('#announce').textContent=button.textContent;window.setTimeout(()=>button.textContent=text[lang].copy,1800);}));
function fromHash(){const m=location.hash.match(/^#(en|ru)(?:-|$)/);if(m&&m[1]!==lang)setLang(m[1]);const target=document.getElementById(location.hash.slice(1));if(target){if(target.hidden){$('#search').value='';filter();}target.scrollIntoView();}}
window.addEventListener('hashchange',fromHash);const hashLang=location.hash.match(/^#(en|ru)(?:-|$)/)?.[1];setLang(hashLang||read('dreamsleeve-agent-lang')||'ru');requestAnimationFrame(fromHash);
})();
'''
html='''<!DOCTYPE html>
<html lang="en" data-theme="light"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="description" content="Dreamsleeve.Agent: offline English / Russian guide to F# agents, ownership, request/reply, backpressure and shutdown on .NET 10."><title>Dreamsleeve.Agent — F# agents · RU / EN</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('dreamsleeve-agent-theme')||(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light')}catch{}</script><style>'''+css+'''</style></head><body id="top"><a class="skip" id="skip" href="#main">Skip to content</a><header class="topbar"><div class="top-inner"><a class="brand" href="#top"><span class="brand-mark" aria-hidden="true">D</span>Dreamsleeve.Agent</a><div class="top-right"><span class="version">.NET 10+</span><div class="languages" role="group" aria-label="Language / Язык"><button type="button" data-language="en" aria-pressed="true">EN</button><button type="button" data-language="ru" aria-pressed="false">RU</button></div><button class="theme" type="button" aria-label="Toggle color theme">Dark</button></div></div></header><noscript><style>article[data-lang][hidden]{display:block!important}</style><div class="noscript">JavaScript is disabled. Both complete language versions are shown below; code can be selected and copied manually.<br>JavaScript отключён. Ниже доступны обе полные версии; код можно выделить и скопировать вручную.</div></noscript><div class="layout"><aside class="sidebar"><div class="sidebar-inner"><label class="search-label" id="search-label" for="search">Find a section</label><div class="searchbox"><input id="search" type="search" placeholder="Timeout, state, shutdown…" autocomplete="off" aria-label="Search documentation sections"><kbd aria-hidden="true">/</kbd></div><p class="search-status" id="search-status" role="status" aria-live="polite"></p><div class="nav-title">In this guide</div><nav class="nav" aria-label="Documentation sections"></nav><div class="sidebar-bottom"><span id="sidebar-title">Source &amp; quick start</span><a href="../Agent.fs">Agent.fs →</a><a href="../README.md" id="readme-link">Quick start →</a></div></div></aside><main id="main" tabindex="-1"><p class="no-results" id="no-results" hidden></p><article data-lang="en">'''+hero_en+''.join(EN)+'''</article><article data-lang="ru" hidden>'''+hero_ru+''.join(RU)+'''</article><footer class="footer"><span id="footer-note">One file. No build. No network.</span><a href="#top" id="top-link">Back to top ↑</a></footer></main></div><div class="sr-only" id="announce" role="status" aria-live="polite"></div><script>'''+js+'''</script></body></html>'''
(project/'docs/index.html').write_text(html,encoding='utf-8')
print(f'Wrote {len(html.encode())} bytes; {len(EN)} sections per language')
